            $display("FAIL: core never halted within %0d cycles", max_cycles);
            errors = errors + 1;
        end else begin
            $display("Halted after %0d cycles. tohost=%0d", cycle_count, tohost_value);
            check(tohost_value, 32'd3, "tohost (n7 = traps taken)");
            check(dut.n_bank.regs[6], 32'd3, "n6 (causes 0+0+3: 2 ILLEGAL, 1 PRIV)");
            check(dut.dmem.mem[248], 32'h3D3FAE6F, "<P> of the 4x4 lattice (+0.046797)");
            check(dut.dmem.mem[249], 32'h3F7210E7, "<P> of the 2x2 lattice (+0.945570)");
            check(dut.dmem.mem[250], 32'h3F800000, "<P> of the 1x1 lattice (+1.000000)");
            check(n_lat, 6, "SWEEP instructions seen");
            check(lat[0], 5389, "cycles of SWEEP L=4");
            check(lat[1], 1357, "cycles of SWEEP L=2");
            check(lat[2], 349, "cycles of SWEEP L=1");
            check(lat[3], 1, "cycles of trapping SWEEP #0");
            check(lat[4], 1, "cycles of trapping SWEEP #1");
            check(lat[5], 1, "cycles of trapping SWEEP #2");
        end

        if (errors == 0) $display("ALL AXISA SWEEP TESTS PASSED");
        else $display("%0d AXISA SWEEP TEST(S) FAILED", errors);
        $finish;
